from pathlib import Path

from docx import Document


DOCX = Path(r"C:\Users\UFANB\Desktop\zxc_liga_gym_updated.docx")
OUT = Path(r"C:\Users\UFANB\Desktop\zxc_liga_gym_updated_tail.docx")


def delete_paragraph(paragraph):
    element = paragraph._element
    element.getparent().remove(element)
    paragraph._p = paragraph._element = None


def add(doc, text=""):
    doc.add_paragraph(text)


def update_tail():
    doc = Document(DOCX)
    marker = "Рисунок 2.52 – Панель тренера"
    marker_index = None
    for index, paragraph in enumerate(doc.paragraphs):
      if paragraph.text.strip() == marker:
          marker_index = index
          break

    if marker_index is None:
        raise RuntimeError("Tail marker not found")

    for paragraph in list(doc.paragraphs)[marker_index + 1:]:
        delete_paragraph(paragraph)

    add(doc, "Работа тренера с медиафайлами")
